/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [5:0] second;
  wire [5:0] minute;

  TopModule dut (
    .clk(clk),
    .rst_n(rst_n),
    .second(second),
    .minute(minute)
  );

  always #5 clk = ~clk;

  integer i;
  initial begin
    #2;
    if (second "'!== 6'"'d0 || minute "'!== 6'"'d0) begin
      "'$display("FAIL: reset state incorrect s=%0d m=%0d", second, minute);
      $finish(1);
    end

    rst_n = 1;

    @(posedge clk);
    #1;
    if (second !== 6'"'d1 || minute "'!== 6'"'d0) begin
      "'$display("FAIL: first tick incorrect s=%0d m=%0d", second, minute);
      $finish(1);
    end

    for (i = 0; i < 59; i = i + 1) @(posedge clk);
    #1;
    if (second !== 6'"'d60 || minute "'!== 6'"'d0) begin
      "'$display("FAIL: second did not reach 60 correctly s=%0d m=%0d", second, minute);
      $finish(1);
    end

    @(posedge clk);
    #1;
    if (second !== 6'"'d1 || minute "'!== 6'"'d1) begin
      "'$display("FAIL: minute rollover incorrect s=%0d m=%0d", second, minute);
      $finish(1);
    end

    repeat ((59 * 60) + 59) @(posedge clk);
    #1;
    if (second !== 6'"'d60 || minute "'!== 6'"'d59) begin
      "'$display("FAIL: pre-60 boundary incorrect s=%0d m=%0d", second, minute);
      $finish(1);
    end

    @(posedge clk);
    #1;
    if (second !== 6'"'d1 || minute "'!== 6'"'d60) begin
      "'$display("FAIL: minute 60 entry incorrect s=%0d m=%0d", second, minute);
      $finish(1);
    end

    repeat (3) @(posedge clk);
    #1;
    if (second !== 6'"'d1 || minute "'!== 6'"'d60) begin
      "'$display("FAIL: stopwatch did not pause at 60 s=%0d m=%0d", second, minute);
      $finish(1);
    end

    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

